function chatPage(id){
  const c=NEX.conversations.find(c=>c.id===id),p=project(c?c.project:S.projectId),isNew=!c;
  if(!canRead(p))return denied();
  const readonly=!canWrite(p)||S.view==='readonly',exhausted=S.view==='budget',pr=provider(c?c.provider:S.provider);
  const key=c?c.id:'new';
  return `<div class="chat-heading"><div><div class="row small muted mb24" style="margin-bottom:8px"><a class="text-link" href="#/project/${p.id}">${icon('folder')}${p.name}</a>${icon('chevron')}<span>Hội thoại</span></div><h1>${isNew?'Hội thoại mới':esc(c.title)}</h1><p>${readonly?'Chỉ xem nội dung':'Được lưu trong dự án'} · ${c?person(c.author).name:me().name}</p></div><div class="row gap6">${btn('Ngữ cảnh','context','file','','data-id="'+p.id+'"')}${ib('more','Tùy chọn hội thoại','chat-options',`data-id="${id||'new'}"`)}</div></div><div class="chat-layout"><section class="chat-column">${readonly?notice('Bạn có quyền xem hội thoại này. Quyền đóng góp cần được cấp riêng để gửi tin nhắn.'):''}${exhausted?notice('Đã chạm hạn mức sử dụng mẫu. Bạn vẫn có thể đọc và xuất hội thoại. Lượt AI mới đang tạm dừng.','amber'):''}${S.view==='error'?notice('Phản hồi bị gián đoạn. Câu hỏi và phần trả lời đã nhận vẫn được giữ lại. Bạn có thể thử lại.','red'):''}<div class="chat-transcript">${isNew&&!S.newMessages[key]?.length?`<div class="new-chat">${mark()}<h2>Cùng mở một hướng nghĩ mới.</h2><p>Bắt đầu hội thoại trong dự án ${p.name}.</p><div class="suggestions">${['Tóm tắt những thông tin quan trọng của dự án','Giúp tôi phân tích một ý tưởng mới','Đề xuất các câu hỏi nghiên cứu tiếp theo','Xây dựng kế hoạch hành động cho tuần này'].map(s=>`<button class="suggestion" data-action="suggest" data-text="${s}">${s} ${icon('arrow')}</button>`).join('')}</div></div>`:!isNew?`<article class="message">${avatar(c.author)}<div class="message-body"><div class="message-author"><strong>${person(c.author).name}</strong><time>09:24</time></div><div class="user-message">${c.id==='c1'?'Hãy phân tích các hướng nghiên cứu cho sản phẩm chăm sóc sức khỏe tại nhà. Tôi muốn hiểu nhu cầu khách hàng, tiêu chí lựa chọn và cách kiểm chứng trước khi quyết định.':`Giúp tôi phân tích chủ đề “${esc(c.title)}” và đề xuất các bước tiếp theo cho dự án.`}</div></div></article><article class="message">${symbol(pr.id)}<div class="message-body"><div class="message-author"><strong>${pr.name}</strong>${pill(pr.mode)}<time>09:24</time></div><div class="ai-message"><p>Dưới đây là khung phân tích để đội ngũ bắt đầu nghiên cứu. Các nội dung trong bản này là <strong>ví dụ minh họa cho giao diện</strong>, cần được kiểm chứng bằng dữ liệu thực tế.</p><h3>1. Bắt đầu từ vấn đề của khách hàng</h3><p>Tập trung vào tình huống sử dụng và kết quả khách hàng mong muốn, trước khi lựa chọn tính năng sản phẩm.</p><div class="table-wrap"><table class="data-table compact no-wide"><thead><tr><th>Góc nhìn</th><th>Câu hỏi cần làm rõ</th></tr></thead><tbody><tr><td><strong>Nhu cầu</strong></td><td>Vấn đề nào xuất hiện thường xuyên?</td></tr><tr><td><strong>Trải nghiệm</strong></td><td>Điều gì khiến giải pháp hiện tại khó sử dụng?</td></tr><tr><td><strong>Quyết định mua</strong></td><td>Khách hàng cần bằng chứng gì để tin tưởng?</td></tr></tbody></table></div><h3>2. Ba hướng để kiểm chứng</h3><ul><li><strong>Phỏng vấn khách hàng:</strong> tìm hiểu một tình huống gần nhất, cách họ đã xử lý và điều còn chưa hài lòng.</li><li><strong>Đối chiếu phản hồi:</strong> nhóm các nhận xét theo vấn đề, tần suất và mức độ ảnh hưởng.</li><li><strong>Thử một giải pháp nhỏ:</strong> dùng phản hồi trực tiếp để điều chỉnh trước khi mở rộng.</li></ul><blockquote>Gợi ý tiếp theo: chọn một nhóm khách hàng cụ thể và xây dựng bộ 5 câu hỏi phỏng vấn.</blockquote><div class="sources">${['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx'].map((name,i)=>`<button class="source" data-action="file-preview" data-id="${i}"><span class="source-num">${i+1}</span>${name}${icon('external')}</button>`).join('')}</div><p class="tiny muted">Tài liệu và trích dẫn minh họa trong prototype.</p></div><div class="message-actions">${ib('copy','Sao chép phản hồi mẫu','copy-answer')}${ib('thumb','Đánh dấu hữu ích','like')}${!readonly?ib('refresh','Thử lại phản hồi mẫu','retry'):''}${ib('branch','Tạo nhánh với AI khác','branch',`data-id="${p.id}"`)}<span class="meta">${pr.name} · 1.240 token · $0.012 mẫu</span></div></div></article>`:''}${(S.newMessages[key]||[]).map(m=>`<article class="message">${m.kind==='user'?avatar(me().id):symbol(S.provider)}<div class="message-body"><div class="message-author"><strong>${m.kind==='user'?me().name:provider(S.provider).name}</strong><time>Vừa xong · Mô phỏng</time></div><div class="${m.kind==='user'?'user-message':'ai-message'}">${esc(m.text).replace(/\n/g,'<br>')}</div></div></article>`).join('')}${S.busy?`<div class="message">${symbol(S.provider)}<div class="message-body"><div class="message-author"><strong>Đang hiển thị phản hồi mẫu</strong></div><div class="typing"><span></span><span></span><span></span></div></div></div>`:''}</div><div class="chat-composer"><label for="chat-prompt" class="sr-only">Nội dung tin nhắn</label><textarea id="chat-prompt" placeholder="${readonly?'Bạn đang ở chế độ chỉ xem':exhausted?'Ngân sách đã hết — tin nhắn mới tạm dừng':'Tiếp tục trao đổi hoặc đặt một câu hỏi...'}" ${readonly||exhausted?'disabled':''}>${esc(S.draft||'')}</textarea><div class="composer-controls"><div class="row gap6"><button class="composer-model" data-action="models" ${readonly?'disabled':''}>${symbol(isNew?S.provider:pr.id)}${isNew?provider(S.provider).name:pr.name}${icon('down')}</button>${ib('paperclip','Chọn tài liệu mẫu','attach',readonly?'disabled':'')}</div><button class="send-button" data-action="${S.busy?'stop':'send'}" data-id="${key}" aria-label="${S.busy?'Dừng mô phỏng':'Gửi tin nhắn mẫu'}" ${readonly||exhausted?'disabled':''}>${icon(S.busy?'stop':'up')}</button></div></div><p class="composer-foot">${iconInlineShield()} Nội dung mô phỏng, không gửi tới AI. Chủ doanh nghiệp có quyền xem dự án công việc.</p></section><aside class="panel context-panel"><div class="section"><div class="row between"><h3>Ngữ cảnh hội thoại</h3>${icon('file')}</div><p>Những thông tin được dùng cho lượt trao đổi này.</p><div class="context-label">DỰ ÁN</div><a href="#/project/${p.id}" class="detail green">${p.name}</a><div class="context-label">NGUỒN AI</div><div class="row gap6">${symbol(pr.id)}<span class="detail">${pr.name} · ${pr.mode}</span></div></div><div class="section"><h3>Tài liệu được chọn <span class="muted">2</span></h3>${['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx'].map((f,i)=>`<button class="mini-file full" data-action="file-preview" data-id="${i}">${icon('file')}<span>${f}</span></button>`).join('')}<button class="text-link mt12" data-action="attach">${icon('plus')}Chọn tài liệu</button></div><div class="section"><h3>Quyền truy cập</h3><div class="avatar-group mt12">${[p.owner,...p.members].slice(0,4).map(uid=>avatar(uid,'sm')).join('')}</div><p class="context-notice">Thành viên dự án và chủ doanh nghiệp có quyền xem. Dữ liệu dự án khác không tự được gửi kèm.</p></div></aside></div>`;
}
function iconInlineShield(){return '<span aria-hidden="true">◇</span>';}
function libraryPage(){let list=visibleChats().filter(c=>(S.libraryProvider==='all'||c.provider===S.libraryProvider)&&(S.librarySource==='all'||(S.librarySource==='hub'?c.source==='Hub':c.source!=='Hub'))&&(!S.librarySearch||`${c.title} ${c.excerpt} ${project(c.project).name}`.toLocaleLowerCase('vi').includes(S.librarySearch.toLocaleLowerCase('vi'))));return `${heading('Kho hội thoại','Một nơi để tìm lại những ý tưởng và câu trả lời hữu ích.',S.role==='owner'?btn('Nhập hội thoại','navigate','','',`data-path="imports"`):'')}<div class="toolbar"><div class="input-icon" style="flex:1">${icon('search')}<input class="input" style="width:100%" id="library-search" aria-label="Tìm trong hội thoại" placeholder="Tìm nội dung, tiêu đề hoặc dự án..." value="${esc(S.librarySearch)}"></div><div class="row"><select class="select" id="library-provider" aria-label="Lọc nguồn AI"><option value="all">Tất cả nguồn AI</option>${NEX.providers.slice(0,3).map(p=>`<option value="${p.id}" ${S.libraryProvider===p.id?'selected':''}>${p.name}</option>`).join('')}</select><select class="select" id="library-source" aria-label="Lọc nguồn hội thoại"><option value="all">Mọi nguồn dữ liệu</option><option value="hub" ${S.librarySource==='hub'?'selected':''}>Tạo trong Hub</option><option value="import" ${S.librarySource==='import'?'selected':''}>Được nhập vào</option></select></div></div>${stateContent()||(list.length?`<div class="small muted mb24">${list.length} hội thoại mẫu trong phạm vi bạn được xem</div><div class="panel"><div class="detail-list">${list.map(c=>`<a href="#/chat/${c.id}" class="conversation-item" style="padding:22px 0;align-items:flex-start">${symbol(c.provider)}<div class="conversation-text"><div class="conversation-title">${esc(c.title)}</div><p class="small muted" style="margin:8px 0;line-height:1.8;white-space:normal">${esc(c.excerpt)}</p><div class="conversation-sub"><span>${project(c.project).name}</span><span>·</span><span>${person(c.author).name}</span><span>·</span><span>${c.date}</span></div></div>${pill(c.source,c.source==='Hub'?'green':'blue')}</a>`).join('')}</div></div>`:emptySearch())}`;}
function integrationsPage(){return `${heading('Nguồn AI','Quản lý kết nối chung và các tài khoản AI của doanh nghiệp.',btn('Thêm kết nối','connect','plus','primary'))}<div class="toolbar"><div class="tabs">${[['api','Kết nối API','4'],['subscriptions','Tài khoản & gói','4']].map(([id,label,n])=>`<button class="tab ${S.integrationTab===id?'active':''}" data-action="integration-tab" data-id="${id}">${label}<span class="count">${n}</span></button>`).join('')}</div><span class="tiny muted">Chỉ chủ doanh nghiệp quản lý kết nối</span></div>${S.integrationTab==='api'?`${notice('Nhân viên sử dụng các kết nối được cấp quyền trong Hub. Khóa truy cập không hiển thị với nhân viên.')}<div class="provider-grid">${NEX.providers.map(p=>`<section class="panel provider-card"><div class="row between"><div class="row">${symbol(p.id,true)}<div><h3>${p.name}</h3><span class="tiny muted">${p.id==='meta'?'Chưa có kết nối API':'NexMO · Kết nối công ty'}</span></div></div>${pill(p.id==='meta'?'Chờ xác minh':'Đã kết nối',p.id==='meta'?'amber dot':'green dot')}</div><p class="provider-intro">${p.hint}</p><div class="tags">${p.id==='meta'?pill('Khả năng tích hợp chưa xác minh','amber'):pill('Chat văn bản')+pill(p.mode)+pill('5 nhân viên')}</div><div class="provider-key">${icon('key')}<span>${p.id==='meta'?'Chưa cấu hình credential':'•••• •••• •••• DEMO'}</span></div><footer><span>${p.id==='meta'?'Không dùng phiên đăng nhập website':`Chi phí mẫu tháng này <strong>${money(p.cost)}</strong>`}</span>${btn(p.id==='meta'?'Xem khả năng':'Quản lý','provider-detail',p.id==='meta'?'info':'settings','',`data-id="${p.id}"`)}</footer></section>`).join('')}</div><p class="tiny muted mt24">Các trạng thái và khóa ở trên đều là dữ liệu mẫu. Prototype không kết nối đến nhà cung cấp.</p>`:`${notice('Gói thuê bao website và kết nối API được quản lý riêng. Ngày gia hạn bên dưới là ví dụ thiết kế.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Nền tảng</th><th>Gói hiện có</th><th>Người quản lý</th><th>Gia hạn mẫu</th><th>Trạng thái</th><th></th></tr></thead><tbody>${NEX.providers.map(p=>`<tr><td><div class="row">${symbol(p.id)}<strong>${p.id==='openai'?'ChatGPT':p.name}</strong></div></td><td>${p.account}</td><td>Minh Trần</td><td>${p.renew}</td><td>${pill(p.id==='meta'?'Miễn phí':'Trả phí',p.id==='meta'?'':'green')}</td><td>${ib('edit','Chỉnh sửa bản ghi tài khoản','subscription',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table><div class="table-footer"><span>4 tài khoản · Chủ doanh nghiệp quản lý</span><span>Thông tin nhập thủ công</span></div></div>`}`;}
function teamPage(){const members=NEX.people.filter(p=>p.id!=='owner'&&(!S.employeeSearch||`${p.name} ${p.job}`.toLocaleLowerCase('vi').includes(S.employeeSearch.toLocaleLowerCase('vi'))));return `${heading('Nhân viên','Cấp quyền sử dụng AI và quản lý hoạt động của đội ngũ.',btn('Mời nhân viên','invite','plus','primary'))}<div class="metrics-strip">${metric('Tổng nhân viên','5','people')}${metric('Đang hoạt động',NEX.people.filter(p=>p.id!=='owner'&&p.status==='active').length,'activity')}${metric('Nguồn AI được cấp','3','plug')}${metric('Chi phí nhân viên','$57.00','wallet')}</div><div class="toolbar"><div class="tabs"><button class="tab active">Tất cả nhân viên <span class="count">5</span></button></div><div class="input-icon">${icon('search')}<input class="input" id="employee-search" aria-label="Tìm nhân viên" placeholder="Tìm tên hoặc công việc..." value="${esc(S.employeeSearch)}"></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nhân viên</th><th>Nguồn AI</th><th>Sử dụng / hạn mức mẫu</th><th>Trạng thái</th><th></th></tr></thead><tbody>${members.map(p=>`<tr><td><button class="row text-left" data-action="employee" data-id="${p.id}">${avatar(p.id)}<span><span class="row-title">${p.name}</span><span class="row-sub" style="display:block">${p.job}</span></span></button></td><td><div class="row gap6">${NEX.providers.slice(0,3).map(pr=>symbol(pr.id)).join('')}</div></td><td class="progress-cell"><div class="row between tiny"><strong>${money(p.cost)}</strong><span class="muted">/ $${p.limit}</span></div><div class="track"><span style="width:${p.cost/p.limit*100}%"></span></div></td><td>${pill(p.status==='locked'?'Đã khóa':'Hoạt động',p.status==='locked'?'red':'green dot')}</td><td>${ib('more',`Quản lý ${p.name}`,'employee',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table><div class="table-footer"><span>${members.length} nhân viên · Không bao gồm chủ doanh nghiệp</span><span>Tháng 11/2026 · Mẫu</span></div></div>${notice('Nhân viên chỉ thấy dự án của mình và dự án được chia sẻ. Bạn có quyền xem toàn bộ dự án công việc.')}`;}
function usagePage(){const owner=S.role==='owner',cost=owner?65.4:18.6,limit=owner?150:30;return `${heading(owner?'Chi phí sử dụng':'Sử dụng của tôi',owner?'Hiểu rõ ngân sách đang được dùng ở đâu, bởi ai và cho việc gì.':'Theo dõi mức sử dụng AI và hạn mức được cấp cho bạn.',`<div class="row">${btn('Tháng 11, 2026','month','calendar')}${owner?btn('Ngân sách','budget','wallet','primary'):''}</div>`)}${notice('Số tiền, hạn mức và biểu đồ là dữ liệu minh họa, không phải báo giá hoặc ngân sách đã được chốt.')}<div class="metrics-strip">${metric('Đã sử dụng',money(cost),'wallet')}${metric('Ngân sách mẫu',money(limit),'chart')}${metric('Còn khả dụng',money(limit-cost),'shield')}${metric('Lượt AI trong tháng',owner?'456':'126','chat')}</div>${S.view==='budget'?notice('Hạn mức mẫu đã hết. Các lượt AI mới tạm dừng; kho hội thoại vẫn truy cập được.','amber'):''}<div class="usage-grid"><section class="panel panel-padding"><div class="panel-head"><h2>Sử dụng 7 ngày gần đây</h2><span class="tiny muted">USD · dữ liệu mẫu</span></div><div class="chart" role="img" aria-label="Biểu đồ cột minh họa chi phí 7 ngày gần đây, chia theo OpenAI, Claude và Gemini">${[35,50,32,68,46,84,62].map((v,i)=>`<div class="bar-group"><div class="bar" style="height:${v}%" title="OpenAI · mẫu"></div><div class="bar c" style="height:${v*.7}%" title="Claude · mẫu"></div><div class="bar g" style="height:${v*.4}%" title="Gemini · mẫu"></div><span class="bar-label">${[27,28,29,30,31,'01','02'][i]}</span></div>`).join('')}</div><div class="chart-legend"><span><i></i>OpenAI</span><span><i class="claude"></i>Claude</span><span><i class="gemini"></i>Gemini</span></div></section><section class="panel panel-padding donut-panel"><h2>Theo nguồn AI</h2><div class="donut" role="img" aria-label="Tỷ trọng chi phí mẫu: OpenAI 48%, Claude 34%, Gemini 18%"><div class="donut-center"><strong>${money(cost)}</strong><p>Tổng sử dụng mẫu</p></div></div><div class="status-list">${NEX.providers.slice(0,3).map(p=>`<div class="provider-status-row">${symbol(p.id)}<span>${p.name}</span><strong>${p.percent}%</strong></div>`).join('')}</div></section></div><div class="section-heading"><h2>${owner?'Sử dụng theo nhân viên':'Các lượt sử dụng gần đây'}</h2>${btn('Xuất báo cáo mẫu','export-usage','download')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>${owner?'Thành viên':'Hội thoại'}</th><th>${owner?'Số lượt AI':'Nguồn AI'}</th><th>${owner?'Dự án':'Thời gian'}</th><th>Chi phí mẫu</th><th>Trạng thái</th></tr></thead><tbody>${owner?NEX.people.map(p=>`<tr><td><div class="row">${avatar(p.id)}<span class="row-title">${p.name}</span></div></td><td>${p.runs}</td><td>${p.projects}</td><td><strong>${money(p.cost)}</strong></td><td>${pill('Đã ghi nhận','green')}</td></tr>`).join(''):visibleChats().filter(c=>c.author==='linh').map((c,i)=>`<tr><td>${c.title}</td><td>${provider(c.provider).name}</td><td>${c.time}</td><td>$0.0${12+i*8}</td><td>${pill('Ước tính','blue')}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted mt12">Chi phí trong Hub và hóa đơn nhà cung cấp được đối soát riêng. Credits và lượt chưa xác định không được mặc định là $0.</p>`;}
function importsPage(){const step=S.importStep;return `${heading('Nhập dữ liệu','Đưa những hội thoại có giá trị về cùng không gian công việc.')}<div class="steps">${[[1,'Chọn nguồn'],[2,'Xem trước & phân loại'],[3,'Kết quả']].map(([n,label],i)=>`${i?'<div class="step-line"></div>':''}<div class="step ${step===n?'active':step>n?'done':''}"><span class="step-num">${step>n?'✓':n}</span>${label}</div>`).join('')}</div>${step===3?`<section class="panel success-panel"><div class="success-symbol">${icon('check')}</div><h2>Đã hoàn tất bản xem trước</h2><p>Đây là kết quả nhập dữ liệu mô phỏng. Không có tệp thật được tải lên hoặc lưu.</p><div class="result-metrics"><div><strong>8</strong><span>Hội thoại đã nhập</span></div><div><strong>2</strong><span>Bản trùng được bỏ qua</span></div><div><strong>1</strong><span>Cần xem lại</span></div></div>${notice('Một hội thoại thiếu tệp đính kèm. Nội dung văn bản vẫn được giữ trong ví dụ mẫu.','amber')}<div class="row" style="justify-content:center">${btn('Nhập nguồn khác','import-reset','upload')}${btn('Mở kho hội thoại','navigate','arrow','primary','data-path="library"')}</div></section>`:`<div class="import-grid"><section class="panel panel-padding">${step===1?`<h2>Hội thoại của bạn đang ở đâu?</h2><p class="small muted mt12">Chọn nền tảng đã xuất dữ liệu để xem cách nhập vào Hub.</p><div class="source-options">${NEX.providers.slice(0,3).map(p=>`<button class="source-option ${S.importProvider===p.id?'active':''}" data-action="import-provider" data-id="${p.id}">${symbol(p.id)}${p.id==='openai'?'ChatGPT':p.name}</button>`).join('')}</div><div class="drop-zone">${icon(S.importReady?'check':'upload')}<strong>${S.importReady?'conversations-demo.json':'Chọn dữ liệu để xem trước'}</strong><p>${S.importReady?'11 hội thoại · 128 KB · Tệp minh họa':'JSON hoặc ZIP export từ nền tảng được hỗ trợ'}</p><button class="btn ${S.importReady?'soft':'primary'} mt12" data-action="sample-file">${S.importReady?'Đã chọn dữ liệu mẫu':'Dùng tệp mẫu'}</button><p class="tiny">Prototype không đọc hoặc tải lên tệp trên máy bạn.</p></div><div class="row between"><span class="tiny muted">Dữ liệu chỉ được gán vào dự án sau bước xem trước.</span>${btn('Tiếp tục','import-next','arrow','primary',S.importReady?'':'disabled')}</div>`:`<div class="row between"><h2>Kiểm tra trước khi nhập</h2>${pill('11 hội thoại mẫu','blue')}</div><div class="field mt24"><label for="import-project">Dự án nhận dữ liệu</label><select class="input" id="import-project">${visibleProjects().map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table compact no-wide"><thead><tr><th>Chọn</th><th>Hội thoại</th><th>Kết quả kiểm tra</th></tr></thead><tbody>${[['Phân tích nhu cầu khách hàng','Sẵn sàng','green'],['So sánh giải pháp trên thị trường','Sẵn sàng','green'],['Gợi ý ý tưởng cho quý IV','Trùng nội dung',''],['Tổng hợp phản hồi người dùng','Thiếu tệp','amber']].map(([t,status,cls],i)=>`<tr><td><input type="checkbox" aria-label="Chọn ${t}" ${i===2?'disabled':'checked'}></td><td>${t}</td><td>${pill(status,cls)}</td></tr>`).join('')}</tbody></table></div>${notice('Các hội thoại không có thông tin tác giả sẽ hiển thị “Chưa xác định”, thay vì gán cho người nhập.')}<div class="row between mt24">${btn('Quay lại','import-back')}${btn('Xem kết quả nhập mẫu','import-next','check','primary')}</div>`}</section><aside class="panel panel-padding project-side"><h3>Một bản sao có nguồn gốc</h3><div class="check-list"><div>${icon('check')}Giữ nguồn và thời điểm nhập</div><div>${icon('check')}Phát hiện bản trùng trước khi lưu</div><div>${icon('check')}Gán vào đúng dự án công việc</div><div>${icon('check')}Báo rõ tệp và nội dung còn thiếu</div></div><div class="divider"></div><p class="small muted">Import là bản chụp dữ liệu tại thời điểm xuất. Các thay đổi trên website nguồn không tự cập nhật vào bản đã nhập.</p><button class="text-link mt12" data-action="import-help">Xem hướng dẫn nhập ${icon('arrow')}</button></aside></div>`}`;}
function settingsPage(){const owner=S.role==='owner';return `${heading('Cài đặt','Điều chỉnh không gian làm việc theo cách đội ngũ của bạn hoạt động.')}<div class="settings-grid"><nav class="settings-nav" aria-label="Mục cài đặt">${(owner?[['workspace','Không gian làm việc'],['access','Quyền & hiển thị'],['notifications','Thông báo'],['profile','Hồ sơ của tôi']]:[['profile','Hồ sơ của tôi'],['notifications','Thông báo']]).map(([id,label])=>`<button class="${(owner?S.settingsTab:(S.settingsTab==='workspace'?'profile':S.settingsTab))===id?'active':''}" data-action="settings-tab" data-id="${id}">${label}</button>`).join('')}</nav><section class="settings-content">${S.settingsTab==='access'&&owner?`<div class="panel panel-padding"><h2>Quyền xem dự án</h2><p class="small muted mt12">Chính sách được áp dụng cho mọi dự án công việc.</p>${notice('Chủ doanh nghiệp xem toàn bộ dự án công việc. Nhân viên chỉ thấy dự án của mình và dự án được chia sẻ.')}<div class="settings-row"><div><strong>Thông báo quyền xem cho nhân viên</strong><p>Hiển thị khi tạo và chia sẻ dự án.</p></div>${pill('Luôn bật','green')}</div><div class="settings-row"><div><strong>Quyền xem tách khỏi quyền đóng góp</strong><p>Quyền đọc không tự cấp quyền gửi tin nhắn hoặc sửa.</p></div>${pill('Đang áp dụng','green')}</div><div class="settings-row"><div><strong>Ghi nhận truy cập và xuất dữ liệu</strong><p>Actor, hành động, tài nguyên và thời điểm.</p></div><a class="text-link" href="#/audit">Xem nhật ký ${icon('arrow')}</a></div></div>`:S.settingsTab==='notifications'?`<div class="panel panel-padding"><h2>Thông báo</h2>${[['Cảnh báo ngân sách','Khi sử dụng đến các ngưỡng được cấu hình.'],['Thay đổi quyền dự án','Khi bạn được thêm hoặc thay đổi quyền.'],['Kết quả nhập dữ liệu','Khi hoàn tất bản nhập hoặc có dữ liệu cần xem lại.']].map(([t,d])=>`<div class="settings-row"><div><strong>${t}</strong><p>${d}</p></div><button class="switch on" data-action="toggle" role="switch" aria-checked="true" aria-label="${t}"></button></div>`).join('')}</div>`:`<div class="panel panel-padding"><h2>${S.settingsTab==='profile'||!owner?'Hồ sơ của tôi':'Thông tin không gian làm việc'}</h2><div class="row mt24 mb24">${S.settingsTab==='profile'||!owner?avatar(me().id,'lg'):'<span class="workspace-logo" style="width:46px;height:46px;font-size:19px">N</span>'}<div><strong>${S.settingsTab==='profile'||!owner?me().name:'NexMO Workspace'}</strong><p class="tiny muted">${S.settingsTab==='profile'||!owner?me().job:'Không gian nội bộ · 6 thành viên'}</p></div></div><form id="settings-form"><div class="field"><label for="settings-name">${S.settingsTab==='profile'||!owner?'Họ và tên':'Tên không gian'}</label><input id="settings-name" class="input" value="${S.settingsTab==='profile'||!owner?me().name:'NexMO Workspace'}"></div><div class="form-grid"><div class="field"><label for="settings-language">Ngôn ngữ</label><select id="settings-language" class="input"><option>Tiếng Việt</option><option>English</option></select></div><div class="field"><label for="settings-zone">Múi giờ</label><select id="settings-zone" class="input"><option>Việt Nam (UTC+7)</option></select></div></div>${btn('Lưu bản xem trước','save-settings','','primary')}</form></div>`}<p class="tiny muted mt12">Thay đổi chỉ mô phỏng trong phiên xem prototype.</p></section></div>`;}
function auditPage(){const events=[['owner','Mở hội thoại','Phân tích khách hàng','eye','09:42'],['linh','Tạo hội thoại','Nghiên cứu thị trường','chat','09:24'],['owner','Điều chỉnh hạn mức','Nhân viên Linh Nguyễn','wallet','09:10'],['huy','Chia sẻ dự án','Nội dung tháng 11','people','08:55'],['owner','Xem kết quả nhập','ChatGPT · 11 hội thoại mẫu','upload','08:40'],['anh','Xuất hội thoại','Phân tích khách hàng','download','Hôm qua']];return `${heading('Nhật ký hoạt động','Theo dõi truy cập, thay đổi quyền và các thao tác quản trị.')}<div class="toolbar"><div class="tabs"><button class="tab active">Tất cả hoạt động</button></div>${btn('Bộ lọc','audit-filter','filter')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Người thực hiện</th><th>Hành động</th><th>Tài nguyên</th><th>Thời gian mẫu</th></tr></thead><tbody>${events.map(([uid,action,resource,ic,time])=>`<tr><td><div class="row">${avatar(uid)}${person(uid).name}</div></td><td><span class="audit-action">${icon(ic)}${action}</span></td><td>${resource}</td><td class="muted">${time}</td></tr>`).join('')}</tbody></table></div>${notice('Nhật ký lưu hành động và tài nguyên liên quan. Nội dung câu hỏi và khóa API không được sao chép vào log.')}`;}
function loginPage(){return `<main class="login-page" id="main"><section class="login-art"><div class="brand">${mark()}<span>nex ai hub</span></div><h1>Một không gian.<br>Mọi ý tưởng.</h1><p>Kết nối những AI bạn cần và giữ tri thức của đội ngũ ở cùng một nơi.</p><div class="orbital"><div class="orbit"></div><div class="orbit second"></div>${mark()}<span class="orbit-provider">O</span><span class="orbit-provider">C</span><span class="orbit-provider">G</span><span class="orbit-provider">M</span></div><footer>NexMO Workspace · Không gian làm việc nội bộ</footer></section><section class="login-form"><h2>Chào mừng trở lại.</h2><p>Đăng nhập vào không gian làm việc của bạn.</p><form id="login-form"><div class="field"><label for="login-email">Email công việc</label><input class="input" id="login-email" type="email" autocomplete="username" value="${me().email}" required></div><div class="field"><div class="row between"><label for="login-password">Mật khẩu</label><button type="button" class="text-link" data-action="forgot">Quên mật khẩu?</button></div><input class="input" id="login-password" type="password" autocomplete="current-password" value="prototype-demo" required><span class="hint">Dữ liệu mẫu — không nhập thông tin đăng nhập thật.</span></div><button type="submit" class="btn primary large full">Vào không gian làm việc ${icon('arrow')}</button></form><div class="divider"></div><div class="eyebrow">CHỌN VAI TRÒ ĐỂ XEM THỬ</div><div class="demo-login-roles"><button class="demo-login-role ${S.role==='owner'?'active':''}" data-action="login-role" data-id="owner">${avatar('owner')}<span>Chủ doanh nghiệp</span></button><button class="demo-login-role ${S.role==='employee'?'active':''}" data-action="login-role" data-id="employee">${avatar('linh')}<span>Nhân viên</span></button></div><div class="prototype-label">PROTOTYPE · KHÔNG XÁC THỰC TÀI KHOẢN THẬT</div></section></main>`;}
